data = sys.stdin.read().split()
n = int(data[0])
a = [int(x) for x in data[1:1 + n]]
dp = [1] * n
for i in range(n):
    for j in range(i):
        if a[j] < a[i] and dp[j] + 1 > dp[i]:
            dp[i] = dp[j] + 1
print(max(dp))

